try{

const VP4_STOP=new Set(['The','A','An','And','But','Or','Of','In','On','To','For','By','At','As','With','From','That','This','These','Those','He','His','Him','She','Her','It','Its','They','Their','I','We','Our','You','Your','Then','So','No','Not','Is','Was','Be','When','Where','Which','Who','Whom','Matthew','Mark','Luke','John','Acts','Romans','Genesis','Exodus','Isaiah','Numbers','Ruth','Samuel','Kings','Chronicles','Ezra','Corinthians','Galatians','Hebrews','Psalms','Psalm','Deuteronomy','Leviticus','Jeremiah']);

const vp4List=(t,side)=>{t=String(t||"");const i=t.search(/UNSUPPORTED-L4 PREMISES/i);if(i<0)return [];let body=t.slice(t.indexOf("\n",i)+1);const e=body.search(/\n[ \t]*(?:#{1,3}\s|---[ \t]*\n|\*\*[A-Z][A-Z\x27 -]{4,}\*\*)/);if(e>=0)body=body.slice(0,e);const out=[];
 for(const p of body.split(/\n(?=[ \t]*\**[ \t]*\d+[.)]\s)/)){const m=p.match(/^\s*\**\s*(\d+)[.)]\s+([\s\S]*)$/);if(!m)continue;const txt=m[2];
  const a=txt.match(/ASSUMES\s*:\s*([\s\S]*?)\s*(?:ROWS GIVE\s*:|\nPRESSED WITH|$)/i);if(!a)continue;const r=txt.match(/ROWS GIVE\s*:\s*([\s\S]*?)\s*(?:\nPRESSED WITH|$)/i);const lk=txt.match(/^\s*\**\s*LINK\s+(\d+)/i);
  out.push({side,n:+m[1],link:lk?+lk[1]:+m[1],assumes:a[1].replace(/\s+/g," ").trim(),rows_give:r?r[1].replace(/\s+/g," ").trim():""});}
 return out;};
const vp4Block=(t,k)=>{t=String(t||'');const H=[...t.matchAll(/^[ \t>*#_-]*LINK\s+(\d+)\b[^\n]*/gmi)];const h=H.find(x=>+x[1]===k);if(!h)return '';const nx=H.find(x=>x.index>h.index);
 let e=nx?nx.index:t.length;const u=t.slice(h.index).search(/UNSUPPORTED-L4 PREMISES/i);if(u>=0&&h.index+u<e)e=t.lastIndexOf('\n',h.index+u);return t.slice(h.index,e).trim();};
const vp4Quotes=b=>[...String(b||'').matchAll(/"([^"\n]{2,})"|“([^”\n]{2,})”/g)].map(m=>m[1]||m[2]);

const S=$('Init Seats').first().json;let RS=null;try{RS=$('Resolve Seats').first().json;}catch(e){RS=null;}
let RGL=null;try{if($('Regrade Load').isExecuted)RGL=$('Regrade Load').first().json;}catch(e){RGL=null;}
let F=null;try{F=RGL?RGL.f:$('Final Output').first().json;}catch(e){F=null;}
const ds=RS&&RS.deepseek&&RS.deepseek.api_model?RS.deepseek:null;
/* pkgEAG (ASK 320, E-ASSUME (a)): a gr2 premise with no ASSUMES takes ASSUMES and ROWS GIVE from the gr1 premise whose quoted defender text matches its quoted [CR] text; matched by text, never by number (the lists renumber). It keeps its gr2 number and LINK. */
const vp4Norm=s=>String(s||'').toLowerCase().replace(/\\+"/g,'"').replace(/[^a-z0-9]+/g,' ').trim();
const vp4Q1=t=>{const m=String(t||'').match(/Quote\s*\[[CD]R\d\]\s*:\s*["“]([\s\S]*?)["”](?=\s*(?:Charge|\n|$))/i)||String(t||'').split(/ASSUMES\s*:/i)[0].match(/["“]([^"”]{12,})["”]/);return m?vp4Norm(m[1]):'';};
const vp4Same=(a,b)=>{if(!a||!b)return false;if(a===b)return true;const[s,l]=a.length<b.length?[a,b]:[b,a];return s.split(' ').length>=6&&l.includes(s);};
const vp4All=t=>{t=String(t||'');const i=t.search(/UNSUPPORTED-L4 PREMISES/i);if(i<0)return [];let body=t.slice(t.indexOf('\n',i)+1);const e=body.search(/\n[ \t]*(?:#{1,3}\s|---[ \t]*\n|\*\*[A-Z][A-Z\x27 -]{4,}\*\*)/);if(e>=0)body=body.slice(0,e);const out=[];for(const p of body.split(/\n(?=[ \t]*\**[ \t]*\d+[.)]\s)/)){const m=p.match(/^\s*\**\s*(\d+)[.)]\s+([\s\S]*)$/);if(!m)continue;const lk=m[2].match(/^\s*\**\s*LINK\s+(\d+)/i);out.push({n:+m[1],link:lk?+lk[1]:+m[1],has:/ASSUMES\s*:/i.test(m[2]),q:vp4Q1(m[2]),txt:m[2]});}return out;};
const vp4G1=(g1,g2)=>{const A=vp4All(g1).filter(p=>p.has&&p.q);const B=vp4All(g2).filter(p=>!p.has&&p.q);const out=[];const used=new Set();for(const b of B){const a=A.find(x=>!used.has(x.n)&&vp4Same(x.q,b.q));if(!a)continue;const one=vp4List(g1.slice(0),'DEFENDER').find(x=>x.n===a.n);if(!one)continue;used.add(a.n);out.push({...one,assumes:one.assumes.replace(/\*+/g,'').replace(/\s+/g,' ').trim(),rows_give:one.rows_give.replace(/\*+/g,'').replace(/\s+/g,' ').trim(),n:b.n,link:b.link,from_gr1:a.n});}return out;};
const P=F?vp4List(F.gr2,'DEFENDER').concat(vp4G1(F.gr1,F.gr2)).concat(vp4List(F.cr3,'CHALLENGER')):[];
const prem=P.map(p=>{const blk=vp4Block(p.side==='DEFENDER'?F.cr3:F.dr3,p.link);return {...p,answer_round:(p.side==='DEFENDER'?'CR3':'DR3'),block:blk,quotes:vp4Quotes(blk)};});
if(!F||!ds||!prem.length)return [{json:{acx_skip:true,why:!F?'no rounds found':!ds?'no DeepSeek model_config row':'no UNSUPPORTED-L4 premise carries ASSUMES',prem,run_token:S.run_token}}];
const PROMPT="You are the assumption enforcer. A premise below was listed against a side as UNSUPPORTED-L4, with the words ASSUMES: <fact>. Your one task: does the answering block's own quoted scripture state each assumed fact?\nThe rule the judges were given: \"UNEXHIBITED also fires, whatever label the side gave the link (SUPPORTED, NARROWED TO or KEPT), when the link ASSUMES as given a fact about a person, house, time or act (for example, that a named person is of a named house) and no quoted row gives that fact.\" And: \"What a link INFERS from its rows is its [L4]: it is graded by the two-layer rule and by the meaning of the verses pressed against it, and never as a missing row (DG-61); an inferred act, such as a begetting or a knowing, is never an ASSUMES.\"\nCommitment 3: scripture is read \"one verse or many read together, precept upon precept; no count of verses decides it.\"\nFor each premise: split ASSUMES into its separate facts (a fact joined to another by \"and\" is its own fact). For each fact answer one of:\nSTATED: the verse words quoted in the answering block, one verse or several read together, give the fact. Quote the words, word for word as the block quotes them, with their reference.\nNOT STATED: no verse words quoted in the block give the fact; the block reaches it only by its own reasoning ([L4]) or not at all.\nINFERRED ACT: the fact is an inferred act (such as a begetting or a knowing), which the rule says is never an ASSUMES.\nRead only the words given to you. Bring no doctrine, no training knowledge and no verse the block does not quote. The side's own sentences are not scripture; only quoted verse words count.\nReply with one line per fact and nothing else:\nASSUME-CHECK: <DEFENDER|CHALLENGER> PREMISE <n> -- FACT <k> \"<the fact>\" -- STATED -- <reference> \"<verse words>\" -- <one sentence>\nASSUME-CHECK: <DEFENDER|CHALLENGER> PREMISE <n> -- FACT <k> \"<the fact>\" -- NOT STATED -- <one sentence>\nASSUME-CHECK: <DEFENDER|CHALLENGER> PREMISE <n> -- FACT <k> \"<the fact>\" -- INFERRED ACT -- <one sentence>";
const user=PROMPT+'\n\n'+prem.map(p=>'######## '+p.side+' PREMISE '+p.n+' (listed against the '+p.side.toLowerCase()+', LINK '+p.link+') ########\nASSUMES: '+p.assumes+'\nROWS GIVE (as the lister wrote them): '+(p.rows_give||'(none)')+'\n\nTHE ANSWERING BLOCK, ['+p.answer_round+'] LINK '+p.link+':\n'+(p.block||'(no LINK '+p.link+' block found in ['+p.answer_round+'])')).join('\n\n');
const body={model:ds.api_model,max_tokens:Math.max(Number(ds.max_tokens)||0,8000),temperature:0,messages:[{role:'system',content:'You check whether quoted scripture states a fact. You bring nothing from outside the words given to you: no doctrine, no training knowledge, no reading of your own. You do not judge who is right.'},{role:'user',content:user}]};
return [{json:{acx_skip:false,body,prem,model:ds.api_model,run_token:S.run_token}}];
}catch(__e){let __rt=null;try{__rt=$('Init Seats').first().json.run_token;}catch(e){}return [{json:{acx_skip:true,why:'Assume Check Build failed: '+String(__e&&__e.message||__e).slice(0,300),prem:[],run_token:__rt}}];}